import db from "../../../lib/db.js"; import { verify as v } from "../../../lib/auth.js"; import { sign } from "../../../lib/token.js"; export async function POST(req){ const b=await req.json(); const u=await db.master.findUnique({ where:{ email:b.email }}); if(!u) return Response.json({ ok:false }); const good=await v(b.password,u.password); if(!good) return Response.json({ ok:false }); return Response.json({ ok:true, token:sign({ id:u.id, email:u.email }) }); }
